#!/usr/bin/env python3
"""FOLIO NLI combo: cross-architecture NLI verifier x 4 generators."""

import json, os, sys, time, argparse
import torch
from collections import Counter
from scipy.stats import binomtest
from transformers import AutoTokenizer, AutoModelForSequenceClassification

CLASSES = ["True", "False", "Unknown"]
WEIGHTS = [1, 3, 5]

TRACE_FILES = {
    "Mistral-7B": "mistral_folio_seed123.json",
    "LLaMA-3.1-8B": "llama8b_folio.json",
    "Qwen2.5-14B": "qwen25_folio.json",
    "Qwen3-14B": "qwen3_folio.json",
}


def parse_folio_problem(text):
    markers = [
        "\n\nDetermine whether the following conclusion is true, false, or uncertain:\n",
        "\n\nDetermine whether the following statement is true, false, or unknown:\n",
        "Determine whether the following conclusion is true, false, or uncertain:",
        "Determine whether the following statement is true, false, or unknown:",
    ]
    for m in markers:
        if m in text:
            parts = text.split(m, 1)
            premises = parts[0].strip()
            if premises.startswith("Given the following premises:\n"):
                premises = premises[len("Given the following premises:\n"):]
            elif premises.startswith("Given the following premises:"):
                premises = premises[len("Given the following premises:"):]
            return premises.strip(), parts[1].strip()
    return text, ""


def sc_answer_alpha(vote_dist):
    if not vote_dist:
        return None
    std_votes = {c: vote_dist.get(c, 0) for c in CLASSES}
    max_count = max(std_votes.values())
    if max_count == 0:
        all_votes = {k: v for k, v in vote_dist.items()}
        max_count = max(all_votes.values())
        tied = sorted([k for k, v in all_votes.items() if v == max_count])
        return tied[0]
    tied = sorted([c for c in CLASSES if std_votes[c] == max_count])
    return tied[0]


def combo_answer_alpha(sc_votes, nli_probs, w):
    combined = {}
    for c in CLASSES:
        combined[c] = sc_votes.get(c, 0) + w * nli_probs.get(c, 0.0)
    max_score = max(combined.values())
    tied = sorted([c for c in CLASSES if abs(combined[c] - max_score) < 1e-9])
    return tied[0]


def mcnemar_exact(b, c):
    n = b + c
    if n == 0:
        return 1.0
    return binomtest(min(b, c), n, 0.5).pvalue


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--verifier", required=True)
    parser.add_argument("--traces-dir", required=True)
    parser.add_argument("--device", default="cuda:0")
    parser.add_argument("--output", required=True)
    parser.add_argument("--max-problems", type=int, default=0)
    args = parser.parse_args()

    os.makedirs(os.path.dirname(args.output) or ".", exist_ok=True)

    print(f"Loading verifier: {args.verifier}")
    t_load = time.time()
    tokenizer = AutoTokenizer.from_pretrained(args.verifier)
    model = AutoModelForSequenceClassification.from_pretrained(args.verifier)
    model.eval()
    if "cuda" in args.device:
        model = model.to(args.device)
    print(f"Model loaded in {time.time()-t_load:.1f}s")

    id2label = model.config.id2label
    nli_to_class = {}
    for idx, label in id2label.items():
        lu = label.upper()
        if "ENTAIL" in lu:
            nli_to_class[int(idx)] = "True"
        elif "CONTRA" in lu:
            nli_to_class[int(idx)] = "False"
        else:
            nli_to_class[int(idx)] = "Unknown"
    print(f"id2label: {id2label} -> {nli_to_class}")

    all_results = {}
    verifier_short = args.verifier.split("/")[-1]

    for gen_name, trace_file in TRACE_FILES.items():
        trace_path = os.path.join(args.traces_dir, trace_file)
        if not os.path.exists(trace_path):
            print(f"\n>>> SKIP {gen_name}: {trace_path} not found")
            continue

        print(f"\n{'='*60}")
        print(f"Generator: {gen_name}")

        with open(trace_path) as f:
            data = json.load(f)

        problems = data["results"]
        if args.max_problems > 0:
            problems = problems[:args.max_problems]
        n = len(problems)
        print(f"Processing {n} problems...")

        gt = {}
        sc_votes = {}
        sc_answers = {}
        problem_texts = {}
        for p in problems:
            pid = p["problem_id"]
            gt[pid] = p["ground_truth"]
            sc_votes[pid] = p["sc_vote_distribution"]
            sc_answers[pid] = p["sc_answer"]
            problem_texts[pid] = p["problem"]

        sc_correct = {pid: (sc_answers[pid] == gt[pid]) for pid in gt}
        sc_n_correct = sum(sc_correct.values())
        sc_acc = sc_n_correct / n
        print(f"SC baseline: {sc_acc:.4f} ({sc_n_correct}/{n})")

        nli_probs_all = {}
        nli_preds = {}
        t0 = time.time()

        pids = list(gt.keys())
        for i, pid in enumerate(pids):
            premises, conclusion = parse_folio_problem(problem_texts[pid])
            if not conclusion:
                nli_probs_all[pid] = {c: 1.0/3 for c in CLASSES}
                nli_preds[pid] = "Unknown"
                print(f"  WARNING: could not parse problem {pid}")
                continue

            inputs = tokenizer(premises, conclusion, return_tensors="pt",
                             truncation=True, max_length=512)
            if "cuda" in args.device:
                inputs = {k: v.to(args.device) for k, v in inputs.items()}

            with torch.no_grad():
                outputs = model(**inputs)

            probs = torch.softmax(outputs.logits, dim=-1)[0].cpu()
            pred_idx = probs.argmax().item()

            nli_probs_all[pid] = {nli_to_class[k]: round(probs[k].item(), 6)
                                  for k in nli_to_class}
            nli_preds[pid] = nli_to_class[pred_idx]

            if (i + 1) % 50 == 0:
                print(f"  {i+1}/{n} done...")

        elapsed = time.time() - t0

        nli_n_correct = sum(1 for pid in gt if nli_preds[pid] == gt[pid])
        nli_acc = nli_n_correct / n
        print(f"NLI standalone: {nli_acc:.4f} ({nli_n_correct}/{n}) in {elapsed:.1f}s")

        combo_results = {}
        per_question = {}
        for w in WEIGHTS:
            b_count = 0
            c_count = 0
            combo_answers = {}

            for pid in pids:
                ca = combo_answer_alpha(sc_votes[pid], nli_probs_all[pid], w)
                combo_answers[pid] = ca
                combo_ok = (ca == gt[pid])
                sc_ok = sc_correct[pid]

                if sc_ok and not combo_ok:
                    b_count += 1
                if not sc_ok and combo_ok:
                    c_count += 1

            combo_n_correct = sum(1 for pid in pids if combo_answers[pid] == gt[pid])
            combo_acc = combo_n_correct / n
            delta_pp = round((combo_acc - sc_acc) * 100, 2)
            p_val = mcnemar_exact(b_count, c_count)

            combo_results[f"w{w}"] = {
                "accuracy": round(combo_acc, 4),
                "correct": combo_n_correct,
                "delta_pp": delta_pp,
                "mcnemar_b": b_count,
                "mcnemar_c": c_count,
                "mcnemar_p": round(p_val, 6),
            }

            sig = "***" if p_val < 0.001 else "**" if p_val < 0.01 else "*" if p_val < 0.05 else ""
            print(f"  Combo w={w}: {combo_acc:.4f} ({combo_n_correct}/{n}), "
                  f"d={delta_pp:+.2f}pp, b={b_count} c={c_count} p={p_val:.6f} {sig}")

        for pid in pids:
            per_question[pid] = {
                "nli_pred": nli_preds[pid],
                "nli_probs": nli_probs_all[pid],
                "sc_answer": sc_answers[pid],
                "gold": gt[pid],
                "sc_correct": sc_correct[pid],
                "nli_correct": nli_preds[pid] == gt[pid],
            }

        nli_right_sc_wrong = sum(1 for pid in pids
                                 if nli_preds[pid] == gt[pid] and sc_answers[pid] != gt[pid])
        sc_right_nli_wrong = sum(1 for pid in pids
                                 if sc_answers[pid] == gt[pid] and nli_preds[pid] != gt[pid])
        both_right = sum(1 for pid in pids
                         if nli_preds[pid] == gt[pid] and sc_answers[pid] == gt[pid])
        both_wrong = sum(1 for pid in pids
                         if nli_preds[pid] != gt[pid] and sc_answers[pid] != gt[pid])

        all_results[gen_name] = {
            "generator": gen_name,
            "verifier": verifier_short,
            "n": n,
            "sc_baseline": round(sc_acc, 4),
            "sc_correct": sc_n_correct,
            "nli_standalone": round(nli_acc, 4),
            "nli_correct": nli_n_correct,
            "combo": combo_results,
            "complementarity": {
                "nli_right_sc_wrong": nli_right_sc_wrong,
                "sc_right_nli_wrong": sc_right_nli_wrong,
                "both_right": both_right,
                "both_wrong": both_wrong,
            },
            "inference_time_s": round(elapsed, 1),
            "per_question": per_question,
        }

    output = {
        "experiment": "FOLIO NLI combo",
        "verifier": args.verifier,
        "verifier_short": verifier_short,
        "dataset": "FOLIO-204",
        "weights": WEIGHTS,
        "generators": all_results,
        "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
    }

    with open(args.output, "w") as f:
        json.dump(output, f, indent=2)
    print(f"\nSaved: {args.output}")

    print(f"\n=== SUMMARY: {verifier_short} ===")
    hdr = f"{'Generator':<15} {'SC':>8} {'NLI':>8} {'w=1':>8} {'w=3':>8} {'w=5':>8} {'BestD':>8} {'p':>10}"
    print(hdr)
    for gen_name, r in all_results.items():
        best_w = max(r["combo"].keys(), key=lambda k: r["combo"][k]["accuracy"])
        best = r["combo"][best_w]
        print(f"{gen_name:<15} {r['sc_baseline']:>7.2%} {r['nli_standalone']:>7.2%} "
              f"{r['combo']['w1']['accuracy']:>7.2%} {r['combo']['w3']['accuracy']:>7.2%} "
              f"{r['combo']['w5']['accuracy']:>7.2%} {best['delta_pp']:>+7.2f}pp {best['mcnemar_p']:>10.6f}")


if __name__ == "__main__":
    main()
SCRIPT_EOF
